
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html,
body,
#root {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #02070d;
  color: white;
  font-family: Inter, Arial, Helvetica, sans-serif;
}

button,
input,
select {
  font-family: inherit;
}

button {
  border: none;
  cursor: pointer;
}

input,
select {
  outline: none;
}

.green {
  color: #00e884 !important;
}

.red {
  color: #ff4057 !important;
}

.app {
  width: 100vw;
  height: 100dvh;
  overflow: hidden;
  display: grid;
  grid-template-rows: 86px 1fr 58px;
  background:
    radial-gradient(circle at top left, rgba(0, 119, 255, 0.14), transparent 35%),
    linear-gradient(180deg, #030914, #01050b);
}

/* AUTH */

.authPage {
  width: 100vw;
  height: 100dvh;
  display: grid;
  place-items: center;
  background:
    radial-gradient(circle at top, rgba(0, 119, 255, 0.18), transparent 35%),
    linear-gradient(135deg, #02070d, #06101c);
  padding: 18px;
}

.authCard {
  width: min(540px, 100%);
  border-radius: 24px;
  background:
    radial-gradient(circle at top right, rgba(0, 119, 255, 0.12), transparent 38%),
    rgba(5, 17, 29, 0.96);
  border: 1px solid rgba(255, 255, 255, 0.14);
  padding: 34px;
  box-shadow: 0 25px 70px rgba(0, 0, 0, 0.45);
}

.registerCard {
  width: min(900px, 100%);
}

.authCard .logo {
  justify-content: center;
  margin-bottom: 22px;
}

.authCard h1 {
  text-align: center;
  font-size: 34px;
  margin-bottom: 8px;
}

.authCard p {
  text-align: center;
  color: #aebbd2;
  margin-bottom: 24px;
}

.authCard label {
  display: block;
  margin-bottom: 8px;
  color: #dbe7ff;
  font-size: 15px;
}

.authCard input {
  width: 100%;
  height: 52px;
  border-radius: 13px;
  background: rgba(2, 9, 18, 0.95);
  border: 1px solid rgba(255, 255, 255, 0.14);
  color: white;
  padding: 0 14px;
  margin-bottom: 15px;
  font-size: 15px;
}

.registerGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}

.primaryBtn {
  width: 100%;
  height: 54px;
  border-radius: 13px;
  background: linear-gradient(135deg, #087cff, #0048ff);
  color: white;
  font-size: 18px;
  font-weight: 900;
}

.authCard small {
  display: block;
  text-align: center;
  color: #aebbd2;
  margin-top: 18px;
}

.authCard small button {
  background: transparent;
  color: #008cff;
  font-weight: 800;
}

/* BROKER TOP HEADER */

.topHeader,
.brokerTopHeader {
  display: grid;
  grid-template-columns: 54px 310px 1px minmax(270px, 1fr) 170px 270px 58px 74px;
  gap: 18px;
  align-items: center;
  padding: 0 34px;
  background:
    radial-gradient(circle at 78% 50%, rgba(0, 87, 255, 0.28), transparent 22%),
    linear-gradient(90deg, #02070d 0%, #071423 50%, #02070d 100%);
  border-bottom: 1px solid rgba(255, 255, 255, 0.09);
  box-shadow:
    inset 0 -1px 0 rgba(0, 119, 255, 0.12),
    0 18px 60px rgba(0, 0, 0, 0.28);
}

.brokerMenuBtn {
  width: 48px;
  height: 48px;
  display: grid;
  align-content: center;
  gap: 7px;
  background: transparent;
}

.brokerMenuBtn span {
  display: block;
  width: 31px;
  height: 3px;
  border-radius: 999px;
  background: #aab6ca;
  box-shadow: 0 0 10px rgba(170, 182, 202, 0.15);
}

.logo,
.brokerLogo {
  display: flex;
  align-items: center;
  gap: 16px;
}

.brokerLogoMark {
  width: 54px;
  height: 54px;
  position: relative;
  display: grid;
  place-items: center;
  background: transparent;
  box-shadow: none;
}

.brokerLogoMark::before,
.brokerLogoMark::after {
  content: "";
  position: absolute;
  inset: 6px;
  border-radius: 11px;
  background: linear-gradient(135deg, #04d8ff 0%, #006dff 45%, #082cff 100%);
  transform: skewY(-18deg) rotate(45deg);
  box-shadow:
    0 0 28px rgba(0, 119, 255, 0.35),
    inset 0 0 18px rgba(255, 255, 255, 0.18);
}

.brokerLogoMark::after {
  inset: 14px;
  background: #071423;
  transform: skewY(-18deg) rotate(45deg);
}

.brokerLogoMark span {
  position: relative;
  z-index: 2;
  color: #008cff;
  font-size: 18px;
  font-weight: 1000;
  transform: skewY(-8deg);
}

.logo strong,
.brokerLogo strong {
  font-size: 34px;
  line-height: 1;
  letter-spacing: -1px;
  white-space: nowrap;
  color: white;
  text-shadow: 0 8px 24px rgba(0, 0, 0, 0.35);
}

.logo span,
.brokerLogo span {
  color: #8d98aa;
}

.brokerLogo strong span {
  color: #8d98aa;
}

.brokerHeaderDivider {
  width: 1px;
  height: 56px;
  background: linear-gradient(180deg, transparent, rgba(255, 255, 255, 0.16), transparent);
}

.walletBox,
.brokerWallet {
  height: 66px;
  border-radius: 0;
  background: transparent;
  color: white;
  border: none;
  text-align: left;
  padding: 0 42px 0 0;
  position: relative;
}

.brokerWallet small {
  display: flex;
  align-items: center;
  gap: 10px;
  color: #008cff;
  font-weight: 1000;
  font-size: 18px;
  letter-spacing: 0.4px;
  text-transform: uppercase;
}

.brokerWallet small i {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #00e884;
  box-shadow: 0 0 18px rgba(0, 232, 132, 0.8);
}

.brokerWallet strong {
  display: block;
  margin-top: 8px;
  font-size: 31px;
  font-weight: 500;
  letter-spacing: 0.3px;
  color: white;
}

.brokerWallet strong em {
  font-style: normal;
  color: #8d98aa;
  font-size: 17px;
  margin-left: 6px;
}

.brokerWallet > span {
  position: absolute;
  right: 5px;
  top: 35px;
  color: white;
  font-size: 24px;
}

.accountSwitch,
.brokerAccountSwitch {
  height: 54px;
  padding: 0;
  border-radius: 13px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  background: transparent;
}

.brokerAccountSwitch button {
  height: 54px;
  border-radius: 13px;
  padding: 0 18px;
  background: rgba(255, 255, 255, 0.035);
  color: #b8c4d8;
  border: 1px solid rgba(255, 255, 255, 0.08);
  font-size: 18px;
  font-weight: 900;
}

.brokerAccountSwitch .active {
  color: white;
  background:
    linear-gradient(135deg, rgba(0, 232, 132, 0.18), rgba(0, 232, 132, 0.05));
  border-color: rgba(0, 232, 132, 0.6);
  box-shadow:
    0 0 28px rgba(0, 232, 132, 0.16),
    inset 0 0 18px rgba(0, 232, 132, 0.12);
}

.brokerAccountSwitch .realActive {
  color: white;
  font-size: 21px;
}

.brokerAccountSwitch .realActive span {
  margin-right: 7px;
  color: #00e884;
}

.depositTop,
.brokerDepositBtn {
  height: 62px;
  border-radius: 12px;
  background: linear-gradient(135deg, #087cff 0%, #065dff 55%, #0048ff 100%);
  color: white;
  font-size: 24px;
  font-weight: 500;
  display: grid;
  grid-template-columns: 1fr 78px;
  align-items: center;
  padding: 0;
  overflow: hidden;
  box-shadow:
    0 0 32px rgba(0, 119, 255, 0.42),
    inset 0 0 28px rgba(255, 255, 255, 0.08);
}

.brokerDepositBtn span {
  display: grid;
  place-items: center;
  height: 100%;
}

.brokerDepositBtn b {
  height: 100%;
  display: grid;
  place-items: center;
  font-size: 28px;
  font-weight: 400;
  background: rgba(255, 255, 255, 0.09);
  border-left: 1px solid rgba(255, 255, 255, 0.07);
}

.bellBtn,
.brokerBellBtn {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: transparent;
  color: #aab6ca;
  position: relative;
  font-size: 0;
}

.brokerBellBtn i {
  font-style: normal;
  font-size: 29px;
  filter: grayscale(1);
  opacity: 0.9;
}

.brokerBellBtn b {
  position: absolute;
  top: -6px;
  right: -4px;
  width: 29px;
  height: 29px;
  border-radius: 50%;
  background: #126dff;
  display: grid;
  place-items: center;
  color: white;
  font-size: 15px;
  font-weight: 1000;
  box-shadow: 0 0 20px rgba(18, 109, 255, 0.6);
}

.avatarBtn,
.brokerAvatarBtn {
  width: 62px;
  height: 62px;
  border-radius: 50%;
  background:
    radial-gradient(circle at center, rgba(255, 255, 255, 0.08), transparent 60%),
    rgba(5, 17, 29, 0.75);
  color: white;
  border: 1px solid rgba(255, 255, 255, 0.17);
  font-size: 26px;
  font-weight: 800;
  position: relative;
}

.brokerAvatarBtn i {
  position: absolute;
  right: 7px;
  bottom: 6px;
  width: 11px;
  height: 11px;
  border-radius: 50%;
  background: #00e884;
  box-shadow: 0 0 16px rgba(0, 232, 132, 0.8);
}

.brokerAvatarBtn span {
  position: absolute;
  right: -22px;
  top: 22px;
  color: #8d98aa;
  font-size: 20px;
}

/* MAIN LAYOUT */

.mainScreen {
  min-height: 0;
  overflow: hidden;
  padding: 8px 10px 0;
}

.page {
  width: 100%;
  height: 100%;
  overflow: hidden;
  display: grid;
  gap: 8px;
}

.hubNav,
.proHero,
.homeStats,
.marketTicker,
.homeLowerGrid > div,
.homeFooter,
.forexSymbolBar,
.forexToolbar,
.proChartPanel,
.proOrderPanel,
.tradeManager,
.tradeTypeRow,
.binaryBox,
.binaryOrderPanel,
.botsTitleRow,
.botStats,
.botFilters,
.botCard,
.settingsHero,
.settingsPanel,
.listPanel {
  background:
    linear-gradient(135deg, rgba(7, 25, 45, 0.95), rgba(3, 12, 24, 0.94)),
    rgba(5, 17, 29, 0.94);
  border: 1px solid rgba(70, 145, 255, 0.2);
  border-radius: 14px;
  box-shadow:
    inset 0 0 42px rgba(0, 119, 255, 0.05),
    0 18px 50px rgba(0, 0, 0, 0.16);
}

.hubNav {
  height: 48px;
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  overflow: hidden;
}

.hubNav button {
  background: transparent;
  color: #aab6ca;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 2px;
  border-bottom: 3px solid transparent;
}

.hubNav button span {
  font-size: 17px;
}

.hubNav button small {
  font-size: 13px;
}

.hubNav .active {
  color: #008cff;
  border-bottom-color: #008cff;
  background: linear-gradient(180deg, rgba(0, 119, 255, 0.12), transparent);
}

/* HOME */

.homePage {
  grid-template-rows: 48px minmax(220px, 1.2fr) 92px 58px 1fr 38px;
}

.proHero {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1.1fr 370px;
  gap: 20px;
  align-items: center;
  padding: 26px 34px;
  overflow: hidden;
  border-color: rgba(0, 119, 255, 0.55);
  background:
    radial-gradient(circle at 60% 50%, rgba(0, 119, 255, 0.25), transparent 32%),
    linear-gradient(135deg, rgba(7, 25, 45, 0.96), rgba(3, 12, 24, 0.96));
}

.heroText {
  z-index: 2;
}

.heroText h1 {
  font-size: clamp(42px, 4.4vw, 68px);
  line-height: 0.98;
  letter-spacing: -1.5px;
}

.heroText h1 span {
  display: block;
  color: #008cff;
}

.heroText p {
  color: #b8c4d8;
  max-width: 520px;
  margin: 16px 0 22px;
  font-size: 17px;
}

.heroText > button {
  height: 44px;
  min-width: 160px;
  border-radius: 11px;
  background: #065dff;
  color: white;
  font-size: 15px;
  font-weight: 1000;
}

.heroFeatureRow {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 18px;
  margin-top: 26px;
}

.heroFeature {
  display: grid;
  grid-template-columns: 42px 1fr;
  align-items: center;
  gap: 10px;
}

.heroFeature > b {
  width: 42px;
  height: 42px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  background: rgba(0, 119, 255, 0.14);
  border: 1px solid rgba(0, 140, 255, 0.4);
  font-size: 20px;
}

.heroFeature strong,
.heroFeature small {
  display: block;
}

.heroFeature small {
  color: #aab6ca;
  margin-top: 2px;
  font-size: 12px;
}

.heroChartGlow {
  height: 100%;
  min-height: 170px;
  opacity: 0.95;
}

.heroChartGlow svg {
  width: 100%;
  height: 100%;
  filter: drop-shadow(0 0 18px rgba(0, 119, 255, 0.55));
}

.livePairCard {
  z-index: 2;
  border-radius: 18px;
  padding: 20px;
  background: rgba(3, 12, 24, 0.85);
  border: 1px solid rgba(70, 145, 255, 0.35);
}

.pairHead {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.pairHead span {
  color: #00e884;
  font-size: 12px;
  font-weight: 900;
  background: rgba(0, 232, 132, 0.1);
  padding: 5px 9px;
  border-radius: 999px;
}

.livePairCard h2 {
  font-size: 38px;
  color: #00e884;
  margin-top: 16px;
}

.livePairCard p {
  color: #00e884;
  font-size: 17px;
  margin: 4px 0 12px;
}

.pairTimes {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 6px;
  margin: 12px 0;
}

.pairTimes button {
  height: 30px;
  border-radius: 8px;
  background: transparent;
  color: #c4d0e4;
  font-weight: 900;
}

.pairTimes .active {
  background: #065dff;
  color: white;
}

.pairActions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.pairActions button {
  height: 52px;
  border-radius: 10px;
  color: white;
  font-size: 20px;
  font-weight: 1000;
}

.pairActions button:first-child {
  background: #065dff;
}

.pairActions button:last-child {
  background: #c40827;
}

.homeStats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  padding: 10px;
}

.statCard {
  display: grid;
  grid-template-columns: 52px 1fr 120px;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.035);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.statCard > b {
  width: 46px;
  height: 46px;
  border-radius: 13px;
  display: grid;
  place-items: center;
  background: rgba(0, 119, 255, 0.14);
  font-size: 22px;
}

.statCard strong {
  display: block;
  font-size: 22px;
}

.statCard span {
  display: block;
  color: #aab6ca;
  margin-top: 4px;
}

.marketTicker {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  overflow: hidden;
}

.tickerItem {
  display: grid;
  grid-template-columns: 34px 1fr 90px 70px 110px;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  border-right: 1px solid rgba(255, 255, 255, 0.08);
}

.tickerItem span {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.08);
}

.tickerItem b,
.tickerItem strong,
.tickerItem em {
  font-style: normal;
  font-size: 14px;
}

.homeLowerGrid {
  display: grid;
  grid-template-columns: 1.1fr 1.1fr 1fr 1fr;
  gap: 10px;
  min-height: 0;
  overflow: hidden;
}

.homeLowerGrid > div {
  min-height: 0;
  padding: 18px;
}

.aiTradingCard {
  display: grid;
  grid-template-columns: 120px 1fr;
  gap: 16px;
  align-items: center;
}

.aiChip {
  height: 120px;
  border-radius: 18px;
  display: grid;
  place-items: center;
  background:
    radial-gradient(circle, rgba(0, 119, 255, 0.55), rgba(0, 119, 255, 0.1)),
    #07111d;
  color: #00a3ff;
  font-size: 42px;
  font-weight: 1000;
  box-shadow: 0 0 40px rgba(0, 119, 255, 0.25);
}

.aiTradingCard h3,
.quickActions h3,
.topMarkets h3,
.featureList h3 {
  font-size: 18px;
  margin-bottom: 10px;
}

.aiTradingCard h3 b {
  font-size: 10px;
  padding: 4px 8px;
  background: #065dff;
  border-radius: 7px;
  margin-left: 6px;
}

.aiTradingCard p {
  color: #aab6ca;
  line-height: 1.4;
  font-size: 13px;
  margin-bottom: 12px;
}

.aiTradingCard button {
  height: 36px;
  min-width: 140px;
  border-radius: 10px;
  background: #065dff;
  color: white;
  font-weight: 1000;
}

.quickActions > div {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
}

.quickActions button {
  min-height: 96px;
  border-radius: 12px;
  background: rgba(0, 119, 255, 0.11);
  color: white;
  border: 1px solid rgba(0, 140, 255, 0.25);
  display: grid;
  place-items: center;
  align-content: center;
  gap: 8px;
  font-size: 24px;
}

.quickActions span {
  font-size: 12px;
  font-weight: 800;
}

.topMarkets h3 {
  display: flex;
  justify-content: space-between;
}

.topMarkets h3 button {
  background: transparent;
  color: #008cff;
  font-weight: 900;
}

.topMarkets p {
  display: grid;
  grid-template-columns: 1fr 90px 70px;
  padding: 8px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  font-size: 13px;
}

.topMarkets em {
  font-style: normal;
  text-align: right;
}

.featureList p {
  display: grid;
  grid-template-columns: 38px 1fr;
  gap: 10px;
  align-items: center;
  margin-bottom: 10px;
}

.featureList p > b {
  width: 34px;
  height: 34px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  background: rgba(0, 119, 255, 0.13);
}

.featureList strong,
.featureList small {
  display: block;
}

.featureList small {
  color: #aab6ca;
  margin-top: 2px;
  font-size: 12px;
}

.homeFooter {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  align-items: center;
  padding: 0 20px;
  color: #c4d0e4;
  font-size: 13px;
}

.lineMini {
  width: 100%;
  height: 48px;
}

.lineMini path {
  fill: none;
  stroke: #065dff;
  stroke-width: 3;
  vector-effect: non-scaling-stroke;
}

.miniSpark {
  width: 100px;
  height: 34px;
}

/* FOREX */

.forexPage {
  grid-template-rows: 48px 54px 38px minmax(210px, 1fr) 116px 94px;
}

.forexSymbolBar {
  display: grid;
  grid-template-columns: 40px 150px 1fr 140px 120px 120px 42px 42px;
  gap: 10px;
  align-items: center;
  padding: 7px 10px;
}

.forexSymbolBar button,
.forexSymbolBar select {
  height: 36px;
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.045);
  color: white;
  border: 1px solid rgba(255, 255, 255, 0.12);
}

.forexSymbolBar select {
  background: #030a13;
  padding: 0 12px;
  font-weight: 900;
}

.forexSymbolBar small {
  color: #aab6ca;
  display: block;
  font-size: 12px;
}

.forexToolbar {
  display: grid;
  grid-template-columns: repeat(6, 70px) 42px 64px 130px 1fr 42px 42px 42px;
  overflow: hidden;
}

.forexToolbar button {
  background: transparent;
  color: white;
  border-right: 1px solid rgba(255, 255, 255, 0.08);
}

.forexToolbar .active {
  color: #008cff;
  border: 1px solid #008cff;
  margin: 5px;
  border-radius: 8px;
}

.proChartPanel {
  overflow: hidden;
  background: #02070d;
}

.chartShell {
  position: relative;
  width: 100%;
  height: 100%;
  background: #02070d;
  overflow: hidden;
}

.chartTopStrip {
  height: 30px;
  display: flex;
  gap: 12px;
  align-items: center;
  padding-left: 70px;
  background: rgba(12, 12, 12, 0.95);
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.chartTopStrip small,
.chartTopStrip strong {
  font-size: 12px;
}

.chartTools {
  position: absolute;
  left: 8px;
  top: 38px;
  bottom: 8px;
  width: 40px;
  z-index: 5;
  display: grid;
  gap: 2px;
}

.chartTools button {
  background: transparent;
  color: #dbe7ff;
  font-size: 14px;
}

.chartShell svg {
  position: absolute;
  left: 58px;
  top: 30px;
  width: calc(100% - 58px);
  height: calc(100% - 30px);
}

.priceTag,
