  font-size: 13px;
}

.profileActionCard span em {
  font-style: normal;
  color: #d5e2f5;
  font-size: 18px;
}

.profileActionCard .verifiedMiniBtn {
  color: #00e884;
  background: rgba(0, 232, 132, 0.12);
  border-color: rgba(0, 232, 132, 0.25);
}

.supportWideCard {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: 76px 1fr 280px 190px;
  gap: 18px;
  align-items: center;
  padding: 18px 22px;
}

.responseTime {
  padding-left: 22px;
  border-left: 1px solid rgba(255, 255, 255, 0.1);
}

.responseTime small {
  display: block;
  color: #aab6ca;
  margin-bottom: 8px;
}

.responseTime strong {
  color: #aab6ca;
  font-size: 14px;
}

.supportWideCard button {
  height: 48px;
  border-radius: 10px;
  color: white;
  font-weight: 900;
  background: rgba(255, 255, 255, 0.035);
  border: 1px solid rgba(255, 255, 255, 0.16);
}

.referralPanel {
  padding: 28px 32px;
  display: grid;
  grid-template-rows: auto auto auto auto auto 1fr auto;
  align-content: start;
}

.referralPanel .profileActionIcon {
  margin-bottom: 18px;
}

.referralPanel label {
  margin-top: 35px;
  margin-bottom: 10px;
  color: #aab6ca;
  font-size: 12px;
  font-weight: 800;
}

.referralLinkBox {
  height: 54px;
  display: grid;
  grid-template-columns: 1fr 42px;
  align-items: center;
  padding: 0 10px 0 18px;
  border-radius: 11px;
  background: rgba(255, 255, 255, 0.035);
  border: 1px solid rgba(255, 255, 255, 0.12);
}

.referralLinkBox span {
  color: #b8c4d8;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.referralLinkBox button {
  width: 38px;
  height: 38px;
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.045);
  color: white;
  border: 1px solid rgba(255, 255, 255, 0.13);
}

.referralStatsBox {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  margin-top: 22px;
  padding: 26px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.035);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.referralStatsBox div + div {
  border-left: 1px solid rgba(255, 255, 255, 0.1);
  padding-left: 28px;
}

.referralStatsBox small {
  display: block;
  color: #aab6ca;
  margin-bottom: 9px;
}

.referralStatsBox strong {
  color: #a646ff;
  font-size: 25px;
}

.referralDashboardBtn {
  height: 52px;
  border-radius: 10px;
  color: white;
  font-size: 15px;
  font-weight: 900;
  background: linear-gradient(135deg, #8d28ff, #b52dff);
}

.proLogoutButton {
  display: grid;
  grid-template-columns: 58px 1fr 30px;
  align-items: center;
  text-align: left;
  padding: 0 34px;
  border-radius: 10px;
  background:
    linear-gradient(90deg, rgba(255, 0, 59, 0.13), rgba(255, 0, 59, 0.04));
  border: 1px solid #ff003b;
  color: white;
}

.proLogoutButton > span {
  color: #ff4057;
  font-size: 32px;
}

.proLogoutButton strong {
  display: block;
  color: #ff4057;
  font-size: 18px;
}

.proLogoutButton small {
  display: block;
  color: #aab6ca;
  margin-top: 5px;
  font-size: 14px;
}

.proLogoutButton em {
  justify-self: end;
  font-size: 34px;
  font-style: normal;
  color: #b8c4d8;
}

/* SETTINGS / HISTORY / REPORTS */

.settingsPage,
.listPage,
.reportsPage {
  grid-template-rows: 78px 1fr;
}

.settingsHero,
.listPage h1,
.reportsPage h1 {
  padding: 18px;
}

.settingsPanel,
.listPanel {
  padding: 18px;
  overflow: hidden;
}

.settingsPanel h2 {
  margin-bottom: 14px;
}

.settingsPanel label {
  min-height: 58px;
  display: grid;
  grid-template-columns: 1fr 260px;
  align-items: center;
  border-bottom: 1px solid rgba(255,255,255,.08);
}

.settingsPanel select {
  height: 38px;
  border-radius: 9px;
  background: #030a13;
  color: white;
  border: 1px solid rgba(255,255,255,.13);
  padding: 0 12px;
}

.toggleGrid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
  margin-top: 14px;
}

.toggleGrid p {
  display: flex;
  justify-content: space-between;
  padding: 12px;
  border-radius: 10px;
  background: rgba(255,255,255,.04);
}

.toggleGrid b {
  width: 40px;
  height: 22px;
  border-radius: 999px;
  background: #065dff;
  position: relative;
}

.toggleGrid b::after {
  content: "";
  position: absolute;
  width: 16px;
  height: 16px;
  right: 3px;
  top: 3px;
  border-radius: 50%;
  background: white;
}

.listPanel div {
  min-height: 44px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid rgba(255,255,255,.08);
}

.listPanel small {
  display: block;
  color: #aab6ca;
}

/* BOTTOM NAV */

.bottomNav {
  margin: 0 10px 8px;
  border-radius: 15px;
  background: rgba(5, 17, 29, 0.98);
  border: 1px solid rgba(255, 255, 255, 0.11);
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  overflow: visible;
}

.bottomNav button {
  background: transparent;
  color: #aab6ca;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 2px;
}

.bottomNav span {
  font-size: 22px;
}

.bottomNav small {
  font-size: 11px;
}

.bottomNav .active {
  color: #008cff;
}

.bottomNav button:nth-child(3) {
  transform: translateY(-16px);
}

.bottomNav button:nth-child(3) span {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: #065dff;
  color: white;
  display: grid;
  place-items: center;
}

/* SIDE MENU */

.menuLayer {
  position: fixed;
  inset: 0;
  z-index: 5000;
  display: flex;
  background: rgba(0,0,0,.5);
}

.menuShade {
  position: fixed;
  inset: 0;
  background: transparent;
}

.sideDrawer {
  width: 460px;
  max-width: 88vw;
  height: 100dvh;
  z-index: 2;
  background:
    radial-gradient(circle at top left, rgba(0,119,255,.2), transparent 35%),
    #04101d;
  border-right: 1px solid rgba(255,255,255,.13);
  padding: 16px;
  display: grid;
  grid-template-rows: 54px 134px 1fr 54px;
  gap: 10px;
}

.drawerTop {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.drawerTop button {
  background: transparent;
  color: white;
  font-size: 38px;
}

.drawerAccount {
  padding: 12px;
  border-radius: 15px;
  background: rgba(5,17,29,.9);
  border: 1px solid rgba(255,255,255,.1);
}

.drawerUser {
  display: grid;
  grid-template-columns: 54px 1fr;
  gap: 10px;
  align-items: center;
}

.drawerUser > div {
  width: 54px;
  height: 54px;
  border-radius: 13px;
  display: grid;
  place-items: center;
  color: #02070d;
  background: linear-gradient(135deg, #00eaff, #065dff);
  font-size: 24px;
  font-weight: 1000;
}

.drawerUser small,
.drawerUser span {
  display: block;
  color: #aab6ca;
  font-size: 12px;
}

.drawerUser small {
  color: #00e884;
  font-weight: 900;
}

.drawerUser strong {
  display: block;
  font-size: 20px;
  margin: 3px 0;
}

.drawerSwitch {
  height: 38px;
  margin-top: 10px;
  border-radius: 10px;
  background: #060b17;
  padding: 4px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4px;
}

.drawerSwitch button {
  border-radius: 8px;
  background: transparent;
  color: #aab6ca;
  font-weight: 900;
}

.drawerSwitch .active {
  background: #00c76f;
  color: white;
}

.drawerGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  overflow: hidden;
}

.drawerBlock {
  border-radius: 13px;
  background: rgba(255,255,255,.035);
  border: 1px solid rgba(255,255,255,.08);
  padding: 8px;
}

.drawerBlock h4 {
  color: #aab6ca;
  font-size: 11px;
  margin-bottom: 6px;
}

.drawerButton {
  width: 100%;
  height: 35px;
  background: transparent;
  color: white;
  display: grid;
  grid-template-columns: 25px 1fr auto 12px;
  align-items: center;
  gap: 4px;
  text-align: left;
  border-radius: 8px;
  padding: 0 5px;
}

.drawerButton:hover {
  background: rgba(0,119,255,.12);
}

.drawerButton span {
  color: #008cff;
}

.drawerButton strong {
  font-size: 12px;
}

.drawerButton b {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: #ff003b;
  display: grid;
  place-items: center;
  font-size: 10px;
}

.drawerButton em {
  font-style: normal;
  color: #aab6ca;
}

.drawerLogout {
  border-radius: 12px;
  background: rgba(255,0,59,.08);
  border: 1px solid #ff003b;
  color: #ff4057;
  font-weight: 900;
  font-size: 17px;
}

/* MODALS */

.modalLayer {
  position: fixed;
  inset: 0;
  z-index: 6000;
  background: rgba(0,0,0,.68);
  backdrop-filter: blur(6px);
  display: grid;
  place-items: center;
  padding: 16px;
}

.depositModal {
  width: 520px;
  max-width: 100%;
  border-radius: 22px;
  background: #202838;
  border: 1px solid rgba(255,255,255,.13);
  padding: 26px;
  position: relative;
}

.closeModal {
  position: absolute;
  right: 16px;
  top: 10px;
  background: transparent;
  color: #aab6ca;
  font-size: 38px;
}

.depositModal h2 {
  font-size: 32px;
  margin-bottom: 8px;
}

.depositModal p {
  color: #aab6ca;
  margin-bottom: 20px;
}

.paymentButton {
  width: 100%;
  min-height: 88px;
  display: grid;
  grid-template-columns: 64px 1fr 32px;
  gap: 16px;
  align-items: center;
  padding: 15px;
  margin-bottom: 14px;
  border-radius: 16px;
  background: #1d2534;
  border: 1px solid #313a4f;
  color: white;
  text-align: left;
}

.paymentButton > span {
  width: 60px;
  height: 60px;
  border-radius: 14px;
  display: grid;
  place-items: center;
  background: #254c58;
  font-size: 26px;
}

.paymentButton strong,
.paymentButton small {
  display: block;
}

.paymentButton small {
  color: #aab6ca;
  margin-top: 5px;
}

.paymentButton b {
  font-size: 34px;
  color: #aab6ca;
}

.modalBack {
  height: 34px;
  border-radius: 999px;
  padding: 0 14px;
  background: #2b3548;
  color: white;
  margin-bottom: 12px;
}

.depositModal label {
  display: block;
  margin-bottom: 7px;
}

.depositModal input {
  width: 100%;
  height: 50px;
  border-radius: 10px;
  background: #151c2a;
  color: white;
  border: 1px solid #313a4f;
  padding: 0 13px;
  margin-bottom: 14px;
}

.modalPrimary {
  width: 100%;
  height: 52px;
  border-radius: 10px;
  background: #00c76f;
  color: white;
  font-weight: 1000;
  font-size: 16px;
}

/* TOAST */

.toast {
  position: fixed;
  right: 16px;
  top: 14px;
  z-index: 7000;
  width: 320px;
  border-radius: 13px;
  background: #07111d;
  border-left: 5px solid #008cff;
  color: white;
  padding: 13px 15px;
  box-shadow: 0 20px 60px rgba(0,0,0,.45);
}

.toast.win {
  border-left-color: #00e884;
}

.toast.loss {
  border-left-color: #ff4057;
}

.toast strong,
.toast span {
  display: block;
}

.toast span {
  color: #aab6ca;
  margin-top: 4px;
}

