.compactTradeToast.toast {
  position: fixed !important;
  z-index: 100000 !important;
  top: max(86px, calc(env(safe-area-inset-top, 0px) + 74px)) !important;
  left: 50% !important;
  right: auto !important;
  bottom: auto !important;
  width: min(340px, calc(100vw - 24px)) !important;
  min-width: 0 !important;
  max-width: 340px !important;
  height: auto !important;
  min-height: 54px !important;
  max-height: none !important;
  margin: 0 !important;
  padding: 9px 11px !important;
  display: grid !important;
  grid-template-columns: 34px minmax(0, 1fr) !important;
  align-items: center !important;
  gap: 9px !important;
  transform: translateX(-50%) !important;
  overflow: hidden !important;
  border-radius: 14px !important;
  border: 1px solid rgba(70, 145, 255, 0.42) !important;
  background: rgba(3, 13, 25, 0.96) !important;
  box-shadow: 0 14px 42px rgba(0, 0, 0, 0.55), inset 0 0 26px rgba(0, 119, 255, 0.07) !important;
  backdrop-filter: blur(14px) !important;
  pointer-events: none !important;
  animation: compactToastIn 0.2s ease-out both !important;
}

.compactTradeToast.toast > i {
  width: 34px !important;
  height: 34px !important;
  display: grid !important;
  place-items: center !important;
  border-radius: 11px !important;
  background: rgba(0, 140, 255, 0.16) !important;
  color: #36a7ff !important;
  font-style: normal !important;
  font-size: 18px !important;
  font-weight: 1000 !important;
}

.compactTradeToast.toast.win {
  border-color: rgba(0, 232, 132, 0.62) !important;
}

.compactTradeToast.toast.win > i {
  background: rgba(0, 232, 132, 0.16) !important;
  color: #00e884 !important;
}

.compactTradeToast.toast.loss {
  border-color: rgba(255, 64, 87, 0.62) !important;
}

.compactTradeToast.toast.loss > i {
  background: rgba(255, 64, 87, 0.16) !important;
  color: #ff4057 !important;
}

.compactTradeToast.toast > div {
  min-width: 0 !important;
  display: block !important;
}

.compactTradeToast.toast strong,
.compactTradeToast.toast span {
  position: static !important;
  width: auto !important;
  height: auto !important;
  margin: 0 !important;
  padding: 0 !important;
  transform: none !important;
  text-align: left !important;
}

.compactTradeToast.toast strong {
  display: block !important;
  color: white !important;
  font-size: 13px !important;
  line-height: 1.15 !important;
}

.compactTradeToast.toast span {
  display: block !important;
  margin-top: 3px !important;
  overflow: hidden !important;
  color: #aebbd2 !important;
  font-size: 10px !important;
  line-height: 1.25 !important;
  white-space: nowrap !important;
  text-overflow: ellipsis !important;
}

@keyframes compactToastIn {
  from { opacity: 0; transform: translate(-50%, -8px) scale(0.98); }
  to { opacity: 1; transform: translate(-50%, 0) scale(1); }
}

.binaryChartWithDigits .proChartCanvas {
  position: relative !important;
