@keyframes binaryPulse {
  from { opacity: 0.55; transform: scale(0.82); }
  to { opacity: 1; transform: scale(1.12); }
}

.chartDigitsOverlay {
  position: absolute !important;
  z-index: 16 !important;
  left: 7px !important;
  right: 7px !important;
  bottom: 7px !important;
  min-width: 0 !important;
  display: grid !important;
  grid-template-columns: repeat(5, minmax(0, 1fr)) !important;
  grid-template-rows: repeat(2, 1fr) !important;
  justify-items: center !important;
  align-items: center !important;
  gap: 4px 7px !important;
  padding: 5px 6px !important;
  border: 1px solid rgba(0, 232, 132, 0.2) !important;
  border-radius: 13px !important;
  background: linear-gradient(180deg, rgba(1, 12, 20, 0.64), rgba(0, 20, 22, 0.82)) !important;
  box-shadow: inset 0 0 24px rgba(0, 232, 132, 0.06), 0 8px 25px rgba(0, 0, 0, 0.34) !important;
  backdrop-filter: blur(6px) !important;
}

.chartDigit {
  position: relative !important;
  width: clamp(31px, 8.9vw, 39px) !important;
  height: clamp(31px, 8.9vw, 39px) !important;
  min-width: 0 !important;
  min-height: 0 !important;
  padding: 0 !important;
  display: grid !important;
  place-content: center !important;
  gap: 1px !important;
  overflow: hidden !important;
  border: 2px solid rgba(140, 163, 194, 0.38) !important;
  border-radius: 50% !important;
  background: rgba(5, 17, 29, 0.94) !important;
  color: #dce8fa !important;
  box-shadow: inset 0 0 12px rgba(255, 255, 255, 0.025) !important;
  transition: border-color 0.2s ease, box-shadow 0.2s ease, background 0.2s ease, transform 0.2s ease !important;
}

.chartDigit strong,
.chartDigit span {
  position: relative !important;
  z-index: 3 !important;
  color: inherit !important;
}

.chartDigit strong {
  font-size: 12px !important;
  line-height: 1 !important;
}

.chartDigit span {
  font-size: 6px !important;
  line-height: 1 !important;
}

.chartDigit.highestDigit:not(.waitingWinner):not(.resultWin):not(.resultLoss) {
  border-color: rgba(0, 232, 132, 0.76) !important;
  background: conic-gradient(from -90deg, rgba(0, 232, 132, 0.78) 0deg 180deg, rgba(5, 17, 29, 0.96) 180deg 360deg) !important;
  box-shadow: 0 0 15px rgba(0, 232, 132, 0.2) !important;
}

.chartDigit.lowestDigit:not(.waitingWinner):not(.resultWin):not(.resultLoss) {
  border-color: rgba(255, 64, 87, 0.76) !important;
  background: conic-gradient(from -90deg, rgba(255, 64, 87, 0.76) 0deg 180deg, rgba(5, 17, 29, 0.96) 180deg 360deg) !important;
  box-shadow: 0 0 15px rgba(255, 64, 87, 0.18) !important;
}

.chartDigit.picked:not(.waitingWinner):not(.resultWin):not(.resultLoss) {
  border-color: #f4f8ff !important;
  background: rgba(239, 246, 255, 0.15) !important;
  color: #ffffff !important;
  box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.14), 0 0 16px rgba(255, 255, 255, 0.18) !important;
}

.chartDigit.currentDigit:not(.resultWin):not(.resultLoss) {
  transform: translateY(-1px) scale(1.04) !important;
}

.chartDigit.waitingWinner:not(.resultWin):not(.resultLoss) {
  border-color: #00e884 !important;
  background: linear-gradient(145deg, #00bf73, #007a4d) !important;
  color: white !important;
  box-shadow: 0 0 18px rgba(0, 232, 132, 0.38), inset 0 0 12px rgba(255, 255, 255, 0.15) !important;
}

.chartDigit.resultWin {
  border-color: #8dffd0 !important;
  background: #00c979 !important;
  color: #ffffff !important;
  box-shadow: 0 0 28px rgba(0, 232, 132, 0.95), inset 0 0 16px rgba(255, 255, 255, 0.28) !important;
  animation: digitWinFlash 0.32s ease-in-out 5 alternate !important;
}

.chartDigit.resultLoss {
  border-color: #ffafba !important;
  background: #e31f42 !important;
  color: #ffffff !important;
  box-shadow: 0 0 28px rgba(255, 64, 87, 0.92), inset 0 0 16px rgba(255, 255, 255, 0.22) !important;
  animation: digitLossFlash 0.32s ease-in-out 5 alternate !important;
}

@keyframes digitWinFlash {
  from { transform: scale(0.96); filter: brightness(0.9); }
  to { transform: scale(1.13); filter: brightness(1.35); }
}

@keyframes digitLossFlash {
  from { transform: scale(0.96); filter: brightness(0.88); }
  to { transform: scale(1.13); filter: brightness(1.3); }
}

