/* ---------- REFERENCE-STYLE DIGIT CIRCLES ---------- */
.chartDigitsOverlay {
  overflow: visible !important;
  padding-bottom: 9px !important;
}

.chartDigit {
  position: relative !important;
  isolation: isolate !important;
  overflow: visible !important;
  border: 0 !important;
  background: #dfe4e9 !important;
  color: #313942 !important;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.22) !important;
}

.chartDigit::before {
  content: "" !important;
  position: absolute !important;
  z-index: 0 !important;
  inset: 4px !important;
  border-radius: 50% !important;
  background: #f8fafc !important;
  box-shadow: inset 0 0 0 1px rgba(35, 47, 60, 0.05) !important;
}

.chartDigit > strong,
.chartDigit > .digitPercent {
  position: relative !important;
  z-index: 2 !important;
  color: #313942 !important;
  text-shadow: none !important;
}

.chartDigit > strong {
  font-size: 12px !important;
  font-weight: 1000 !important;
}

.chartDigit > .digitPercent {
  font-size: 6.5px !important;
  font-weight: 750 !important;
}

.chartDigit.highestDigit:not(.waitingWinner):not(.resultWin):not(.resultLoss) {
  border: 0 !important;
  background: conic-gradient(
    #dfe4e9 0deg 132deg,
    #20b99b 132deg 228deg,
    #dfe4e9 228deg 360deg
  ) !important;
  box-shadow: 0 0 0 1px rgba(32, 185, 155, 0.16), 0 3px 8px rgba(0, 0, 0, 0.24) !important;
}

.chartDigit.lowestDigit:not(.waitingWinner):not(.resultWin):not(.resultLoss) {
  border: 0 !important;
  background: conic-gradient(
    #dfe4e9 0deg 132deg,
    #ff4d5e 132deg 228deg,
    #dfe4e9 228deg 360deg
  ) !important;
  box-shadow: 0 0 0 1px rgba(255, 77, 94, 0.14), 0 3px 8px rgba(0, 0, 0, 0.24) !important;
}

.chartDigit.picked:not(.waitingWinner):not(.resultWin):not(.resultLoss) {
  background: #ffffff !important;
  box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.96), 0 0 0 4px rgba(168, 187, 211, 0.42), 0 3px 9px rgba(0, 0, 0, 0.24) !important;
}

.chartDigit.waitingWinner,
.chartDigit.resultWin,
.chartDigit.resultLoss {
  color: white !important;
}

.chartDigit.waitingWinner::before,
.chartDigit.resultWin::before,
.chartDigit.resultLoss::before {
  inset: 2px !important;
  box-shadow: none !important;
}

.chartDigit.waitingWinner,
.chartDigit.resultWin {
  background: #00d184 !important;
}

.chartDigit.waitingWinner::before,
.chartDigit.resultWin::before {
  background: linear-gradient(145deg, #00dd8c, #009c64) !important;
}

.chartDigit.resultLoss {
  background: #f03b52 !important;
}

.chartDigit.resultLoss::before {
  background: linear-gradient(145deg, #ff5268, #cf1735) !important;
}

.chartDigit.waitingWinner > strong,
.chartDigit.waitingWinner > .digitPercent,
.chartDigit.resultWin > strong,
.chartDigit.resultWin > .digitPercent,
.chartDigit.resultLoss > strong,
.chartDigit.resultLoss > .digitPercent {
  color: white !important;
}

.movingDigitCursor {
  position: absolute !important;
  z-index: 8 !important;
  left: 50% !important;
  bottom: -8px !important;
  width: 0 !important;
  height: 0 !important;
  display: block !important;
  opacity: 0 !important;
  transform: translateX(-50%) scale(0.72) !important;
  border-left: 5px solid transparent !important;
  border-right: 5px solid transparent !important;
  border-bottom: 7px solid #ff4d42 !important;
  filter: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.45)) !important;
  transition: opacity 0.16s ease, transform 0.16s ease !important;
  pointer-events: none !important;
}

.chartDigit.currentDigit .movingDigitCursor {
  opacity: 1 !important;
  transform: translateX(-50%) scale(1) !important;
  animation: digitCursorPulse 0.75s ease-in-out infinite alternate !important;
}

@keyframes digitCursorPulse {
  from { transform: translateX(-50%) translateY(1px) scale(0.9); }
  to { transform: translateX(-50%) translateY(-1px) scale(1.04); }
}

