}

.chartDigit::before {
  content: "" !important;
  position: absolute !important;
  inset: 4px !important;
  z-index: 0 !important;
  border-radius: 50% !important;
  background: #eef2f5 !important;
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.05) !important;
}

.chartDigit > strong,
.chartDigit > .digitPercent,
.chartDigit.highestDigit > strong,
.chartDigit.highestDigit > .digitPercent,
.chartDigit.picked > strong,
.chartDigit.picked > .digitPercent {
