  font-weight: 800 !important;
}

.chartDigit.highestDigit:not(.resultWin):not(.resultLoss) {
  background: conic-gradient(
    from -90deg,
    #20bf75 0deg 180deg,
    #ffffff 180deg 360deg
  ) !important;
  box-shadow:
    0 0 0 2px rgba(255, 255, 255, 0.98),
    0 0 0 4px rgba(32, 191, 117, 0.18),
    0 4px 10px rgba(0, 0, 0, 0.24) !important;
}

.chartDigit.picked:not(.resultWin):not(.resultLoss) {
