/* ---------- Digit board ---------- */
.finalBinaryTradePage .chartDigit,
.finalBinaryTradePage .chartDigit:not(.resultWin):not(.resultLoss) {
  position: relative !important;
  isolation: isolate !important;
  overflow: visible !important;
  border: 0 !important;
  border-radius: 50% !important;
  background: #e5e9ed !important;
  box-shadow:
    0 0 0 1px rgba(255,255,255,.96),
    0 4px 12px rgba(0,0,0,.38) !important;
  opacity: 1 !important;
}

.finalBinaryTradePage .chartDigit::before {
  content: "" !important;
  position: absolute !important;
  inset: 5px !important;
  z-index: 1 !important;
  border-radius: 50% !important;
  border: 1px solid rgba(255,255,255,.12) !important;
  background: #05080d !important;
  box-shadow:
    inset 0 0 0 1px rgba(0,0,0,.9),
    inset 0 1px 4px rgba(255,255,255,.07) !important;
}

.finalBinaryTradePage .chartDigit::after {
  content: "" !important;
  position: absolute !important;
  inset: 0 !important;
  z-index: 3 !important;
  border-radius: 50% !important;
  pointer-events: none !important;
  background: conic-gradient(
    from -90deg,
    transparent 0deg 130deg,
    #76808c 130deg 230deg,
    transparent 230deg 360deg
  ) !important;
  -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 5px), #000 calc(100% - 4px)) !important;
  mask: radial-gradient(farthest-side, transparent calc(100% - 5px), #000 calc(100% - 4px)) !important;
}

.finalBinaryTradePage .chartDigit > strong,
.finalBinaryTradePage .chartDigit > .digitPercent {
  position: relative !important;
  z-index: 4 !important;
  color: #fff !important;
  text-shadow: 0 1px 2px rgba(0,0,0,.9) !important;
}

/* Highest: a clear green half ring around the bottom. */
.finalBinaryTradePage .chartDigit.highestDigit:not(.resultWin):not(.resultLoss)::after {
  background: conic-gradient(
    from -90deg,
    transparent 0deg 90deg,
    #18c8a6 90deg 270deg,
    transparent 270deg 360deg
  ) !important;
  filter: drop-shadow(0 0 4px rgba(24,200,166,.55));
}

/* Lowest: a smaller red warning arc. */
.finalBinaryTradePage .chartDigit.lowestDigit:not(.resultWin):not(.resultLoss)::after {
  background: conic-gradient(
    from -90deg,
    transparent 0deg 145deg,
    #ff5266 145deg 215deg,
    transparent 215deg 360deg
  ) !important;
  filter: drop-shadow(0 0 3px rgba(255,82,102,.48));
}

/* User-selected digit is white inside until a contract starts. */
.finalBinaryTradePage .chartDigit.picked:not(.winningTarget):not(.resultWin):not(.resultLoss)::before {
  background: #fff !important;
  border-color: #d8dee5 !important;
  box-shadow: inset 0 -4px 8px rgba(18,30,42,.09) !important;
}

.finalBinaryTradePage .chartDigit.picked:not(.winningTarget):not(.resultWin):not(.resultLoss) > strong,
.finalBinaryTradePage .chartDigit.picked:not(.winningTarget):not(.resultWin):not(.resultLoss) > .digitPercent {
  color: #05080d !important;
  text-shadow: none !important;
}

/* Digits that can win the active contract visibly turn green. */
.finalBinaryTradePage .chartDigit.winningTarget:not(.resultWin):not(.resultLoss) {
  background: #42f0b7 !important;
  box-shadow:
    0 0 0 2px rgba(195,255,233,.92),
    0 0 15px rgba(0,225,145,.38) !important;
}

.finalBinaryTradePage .chartDigit.winningTarget:not(.resultWin):not(.resultLoss)::before {
  background: linear-gradient(145deg, #0ea978, #046044) !important;
  border-color: rgba(219,255,241,.75) !important;
}

.finalBinaryTradePage .chartDigit.winningTarget:not(.resultWin):not(.resultLoss)::after {
  background: conic-gradient(#26e4ab 0deg 360deg) !important;
}

.finalBinaryTradePage .chartDigit.resultWin {
  background: #c4ffe9 !important;
  opacity: 1 !important;
  animation: publicWinFlash .28s ease-in-out 6 alternate !important;
  box-shadow:
    0 0 0 3px #fff,
    0 0 28px rgba(0,255,155,.98),
    0 0 50px rgba(0,255,155,.58) !important;
}

.finalBinaryTradePage .chartDigit.resultWin::before {
  background: radial-gradient(circle at 34% 24%, #a6ffdc, #00e68a 50%, #007d4b) !important;
}

.finalBinaryTradePage .chartDigit.resultWin::after {
  background: #00ff99 !important;
}

.finalBinaryTradePage .chartDigit.resultLoss {
  background: #ffd0d7 !important;
  opacity: 1 !important;
  animation: publicLossFlash .28s ease-in-out 6 alternate !important;
  box-shadow:
    0 0 0 3px #fff,
    0 0 28px rgba(255,49,78,.98),
    0 0 50px rgba(255,49,78,.56) !important;
}

.finalBinaryTradePage .chartDigit.resultLoss::before {
  background: radial-gradient(circle at 34% 24%, #ffa0af, #ff304f 50%, #94071f) !important;
}

.finalBinaryTradePage .chartDigit.resultLoss::after {
  background: #ff304f !important;
}

.finalBinaryTradePage .chartDigit.resultWin > strong,
.finalBinaryTradePage .chartDigit.resultWin > .digitPercent,
.finalBinaryTradePage .chartDigit.resultLoss > strong,
.finalBinaryTradePage .chartDigit.resultLoss > .digitPercent {
  color: #fff !important;
  text-shadow: 0 1px 3px rgba(0,0,0,.72) !important;
}

.finalBinaryTradePage .chartDigit:disabled {
  opacity: 1 !important;
  filter: none !important;
}

.finalBinaryTradePage .movingDigitCursor {
  position: absolute !important;
  z-index: 20 !important;
  left: 50% !important;
  bottom: -10px !important;
  width: 0 !important;
  height: 0 !important;
  opacity: 0 !important;
  border-left: 6px solid transparent !important;
  border-right: 6px solid transparent !important;
  border-bottom: 9px solid #ff5a45 !important;
  transform: translateX(-50%) scale(.72) !important;
  filter: drop-shadow(0 1px 3px rgba(255,76,57,.7)) !important;
  transition: opacity .22s ease, transform .55s cubic-bezier(.2,.72,.22,1) !important;
  pointer-events: none !important;
}

.finalBinaryTradePage .chartDigit.currentDigit .movingDigitCursor,
.finalBinaryTradePage .finalDigitBoard.isTrading .chartDigit.currentDigit .movingDigitCursor {
  opacity: 1 !important;
  transform: translateX(-50%) scale(1) !important;
  animation: publicCursorPulse 1.15s ease-in-out infinite alternate !important;
}

@keyframes publicCursorPulse {
  from { transform: translateX(-50%) translateY(1px) scale(.94); filter: brightness(.95) drop-shadow(0 1px 2px rgba(255,76,57,.55)); }
  to { transform: translateX(-50%) translateY(-2px) scale(1.08); filter: brightness(1.25) drop-shadow(0 0 6px rgba(255,76,57,.9)); }
}

@keyframes publicWinFlash {
  from { transform: scale(.96); filter: brightness(.96); }
  to { transform: scale(1.1); filter: brightness(1.42); }
}

@keyframes publicLossFlash {
  from { transform: scale(.96); filter: brightness(.94); }
  to { transform: scale(1.1); filter: brightness(1.35); }
}

