.finalBinaryTradePage .chartDigit.currentDigit:not(.resultWin):not(.resultLoss) {
  transform: translateY(-1px) scale(1.035) !important;
}

.finalBinaryTradePage .digitRingGraphic {
  position: absolute !important;
  inset: -1px !important;
  z-index: 1 !important;
  width: calc(100% + 2px) !important;
  height: calc(100% + 2px) !important;
  overflow: visible !important;
  pointer-events: none !important;
  filter: drop-shadow(0 3px 5px rgba(0, 0, 0, 0.52)) !important;
}

.finalBinaryTradePage .digitRingGraphic circle,
.finalBinaryTradePage .digitRingGraphic path {
  fill: none !important;
  stroke-width: 11 !important;
  stroke-linecap: butt !important;
  stroke-linejoin: round !important;
  vector-effect: non-scaling-stroke !important;
}

/* Every digit starts as a balanced dark-grey ring. */
.finalBinaryTradePage .digitRingGreyBase {
  stroke: #5d6874 !important;
}

/* Highest percentage: green upper semicircle; grey remains below. */
.finalBinaryTradePage .digitRingHighestGreenArc {
  stroke: #18c8a6 !important;
  stroke-width: 11.5 !important;
  filter: drop-shadow(0 0 4px rgba(24, 200, 166, 0.62)) !important;
}

/* Lowest percentage: a red quarter centred exactly at the bottom. */
.finalBinaryTradePage .digitRingLowestRedArc {
  stroke: #ff334b !important;
  stroke-width: 12 !important;
  stroke-linecap: round !important;
  filter: drop-shadow(0 0 4px rgba(255, 51, 75, 0.72)) !important;
}

/* All middle percentages receive a white arc balanced by grey. */
.finalBinaryTradePage .digitRingBalanceArc {
  stroke: #f3f5f7 !important;
  stroke-width: 11.25 !important;
}

/* Lower percentages show a smaller white arc at the bottom. */
.finalBinaryTradePage .digitRingBalanceArc.lowerBalanceArc {
  filter: drop-shadow(0 0 2px rgba(255, 255, 255, 0.2)) !important;
}

/* Values nearest the highest show up to a white upper half. */
.finalBinaryTradePage .digitRingBalanceArc.upperBalanceArc {
  filter: drop-shadow(0 0 3px rgba(255, 255, 255, 0.28)) !important;
}

/* Black face with a clearly readable digit and percentage. */
.finalBinaryTradePage .digitFace {
  position: absolute !important;
  inset: 8px !important;
  z-index: 3 !important;
  display: grid !important;
  place-content: center !important;
  align-content: center !important;
  justify-items: center !important;
  gap: 3px !important;
  border-radius: 50% !important;
  border: 1px solid rgba(255, 255, 255, 0.08) !important;
  background: #05080d !important;
  color: #ffffff !important;
  box-shadow:
    inset 0 1px 5px rgba(255, 255, 255, 0.05),
    inset 0 -2px 5px rgba(0, 0, 0, 0.75) !important;
}

.finalBinaryTradePage .digitFace > strong,
.finalBinaryTradePage .digitFace > .digitPercent {
  position: relative !important;
  z-index: 4 !important;
  margin: 0 !important;
  padding: 0 !important;
  color: inherit !important;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.92) !important;
}

.finalBinaryTradePage .digitFace > strong {
  font-size: 16px !important;
  line-height: 1 !important;
  font-weight: 1000 !important;
}

.finalBinaryTradePage .digitFace > .digitPercent {
  font-size: 8px !important;
  line-height: 1 !important;
  font-weight: 900 !important;
}

/* Selection never hides a number or percentage. */
.finalBinaryTradePage .chartDigit.picked:not(.winningTarget):not(.resultWin):not(.resultLoss) .digitFace {
  border-color: #d9e1e8 !important;
  background: linear-gradient(145deg, #ffffff, #e8edf1) !important;
  color: #081019 !important;
  box-shadow:
    inset 0 -4px 8px rgba(24, 39, 54, 0.1),
    0 0 0 2px rgba(86, 181, 255, 0.28) !important;
}

.finalBinaryTradePage .chartDigit.picked:not(.winningTarget):not(.resultWin):not(.resultLoss) .digitFace > strong,
.finalBinaryTradePage .chartDigit.picked:not(.winningTarget):not(.resultWin):not(.resultLoss) .digitFace > .digitPercent {
  color: #081019 !important;
  text-shadow: none !important;
  opacity: 1 !important;
  visibility: visible !important;
}

/* Potential winners remain green only while a contract is active. */
.finalBinaryTradePage .chartDigit.winningTarget:not(.resultWin):not(.resultLoss) .digitRingGraphic circle,
.finalBinaryTradePage .chartDigit.winningTarget:not(.resultWin):not(.resultLoss) .digitRingGraphic path {
  stroke: #32e6ae !important;
}

.finalBinaryTradePage .chartDigit.winningTarget:not(.resultWin):not(.resultLoss) .digitFace {
  border-color: rgba(197, 255, 232, 0.78) !important;
  background: linear-gradient(145deg, #14a878, #036044) !important;
  color: #ffffff !important;
  box-shadow: 0 0 14px rgba(0, 225, 145, 0.36) !important;
}

.finalBinaryTradePage .chartDigit.resultWin .digitRingGraphic circle,
.finalBinaryTradePage .chartDigit.resultWin .digitRingGraphic path {
  stroke: #00f098 !important;
}

.finalBinaryTradePage .chartDigit.resultWin .digitFace {
  border-color: #c7ffe8 !important;
  background: radial-gradient(circle at 34% 24%, #9dffda, #00d884 54%, #007d4a) !important;
  color: #ffffff !important;
  box-shadow: 0 0 24px rgba(0, 255, 153, 0.92) !important;
}

.finalBinaryTradePage .chartDigit.resultLoss .digitRingGraphic circle,
.finalBinaryTradePage .chartDigit.resultLoss .digitRingGraphic path {
  stroke: #ff3553 !important;
}

.finalBinaryTradePage .chartDigit.resultLoss .digitFace {
  border-color: #ffd0d8 !important;
  background: radial-gradient(circle at 34% 24%, #ff9dae, #ff304f 54%, #93061f) !important;
  color: #ffffff !important;
  box-shadow: 0 0 24px rgba(255, 48, 79, 0.9) !important;
}

/* Full orange pointer remains visible below either row. */
.finalBinaryTradePage .movingDigitCursor {
  position: absolute !important;
  left: 50% !important;
  bottom: -17px !important;
  z-index: 999 !important;
  display: block !important;
  width: 0 !important;
  height: 0 !important;
  margin: 0 !important;
  opacity: 0 !important;
  visibility: hidden !important;
  transform: translateX(-50%) translateY(2px) scale(0.92) !important;
  border-left: 8px solid transparent !important;
  border-right: 8px solid transparent !important;
  border-top: 0 !important;
  border-bottom: 12px solid #ff5a3f !important;
  filter: drop-shadow(0 2px 4px rgba(255, 90, 63, 0.64)) !important;
  pointer-events: none !important;
}

.finalBinaryTradePage .chartDigit.currentDigit .movingDigitCursor {
  opacity: 1 !important;
  visibility: visible !important;
  transform: translateX(-50%) translateY(0) scale(1) !important;
  animation: rankedDigitCursorPulse 0.65s ease-in-out infinite alternate !important;
}

.finalBinaryTradePage .chartDigit.topDigitRow.currentDigit .movingDigitCursor {
  bottom: -18px !important;
  z-index: 1200 !important;
}

@keyframes rankedDigitCursorPulse {
  from { filter: drop-shadow(0 1px 2px rgba(255, 90, 63, 0.42)); }
  to { filter: drop-shadow(0 3px 7px rgba(255, 90, 63, 0.88)); }
}

